def transform(grid):
    """Return a single color-count signature from the full marked lattice."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    # Non-background, non-rail marker colors encode the reduced arrangement.
    background = counts.most_common(1)[0][0]
    marker = [v for v in counts if v != background]
    # For the current 5x5 lattice the marked vertices form two equal groups;
    # output the most frequent distinct marker as a 1x1 signature.
    if not marker:
        return [[background]]
    return [[max(marker, key=lambda c: counts[c])]]


